# All three released pairs appear seated and both grippers are open.
# Return both arms toward the saved origin joints, stopping immediately on official terminal feedback.
obs = get_observation()
start_joints = {k: np.array(v) for k,v in obs['state'].items() if k.endswith('joint_state')}
for i in range(100):
    if control['halted'] or control['remaining'] <= 0:
        break
    t = min(1.0, (i+1)/80.0)
    action = {}
    for arm in ['left','right']:
        key = arm + '_arm_joint_state'
        action[key] = start_joints[key]*(1-t) + origin[key]*t
        action[arm+'_ee_joint_state'] = [1.0]
    obs, reward, terminated, truncated, info = step(action)
    control['remaining'] -= 1
    control['halted'] = terminated or truncated
    if control['halted']:
        print('terminal', reward, info)
print('remaining',control['remaining'], 'halted',control['halted'])

